      case 25:
        dt =  DataType.UINT;
        break;
      case 26:
        dt =  DataType.LONG;
        break;
      case 27:
        dt =  DataType.ULONG;
        break;
      default:
        throw new IllegalStateException("unknown type= " + type);
    }

    if (v != null) {
      v.setDataType(dt);
    }

    return dt;
  }

