public K pollKey()
    {
        // Scan through the buckets until a non empty one is found.
        int i = 0;

        for (; i < n; i++)
        {
            if (!maps[i].isEmpty())
            {
                break;
            }

            // If all maps are empty then the whole data structure is emtpy.
            if (i == (n - 1))
            {
                return null;
            }
        }

        return maps[i].keySet().iterator().next();
    }

