		if(latitudeAndLongitude == null || latitudeAndLongitude.length == 0) {
			return 0.0;
		}

		if(latitudeAndLongitude.length > 1) {
			return toDoubleSafe(latitudeAndLongitude[0]);
		}

		return 0.0;
	}

