public static boolean sleep(long milliseconds) {
    //checking if we got pre-interrupted.
    boolean interrupted = Thread.interrupted();
    if (!interrupted) {
      try {
        Thread.sleep(milliseconds);
      } catch (InterruptedException ex) {
        interrupted = true;
        // clearing the interrupt flag
        Thread.interrupted();
      }
    }
    return !interrupted;
  }

