public long timeToThrottleNanos()
    {
        long now = System.nanoTime();
        long remainingNanos = (cycleTimeNanos + lastCheckTimeNanos) - now;

        if ((remainingNanos <= 0))
        {
            firstCheckCall = false;
            lastCheckTimeNanos = now;

            return remainingNanos;
        }
        else if (firstCheckCall)
        {
            firstCheckCall = false;
            lastCheckTimeNanos = now;

            return 0;
        }
        else
        {
            return remainingNanos;
        }
    }

