    switch (vendor) {
      case ORACLE:
        switch (jdbcType) {
          case -101: return "TIMESTAMP WITH TIME ZONE";
          case -102: return "TIMESTAMP WITH LOCAL TIME ZONE";
        }
        break;
    }

    return "Unknown";
  }

