			System.err.println(this.getAppName() + ": target " + this.target + " not supported in stg file <" + fileName + ">");
			return -1;
		}

		System.out.println(this.getAppName() + ": generating scripts for target: " + this.target);
		System.out.println();
		return 0;
	}

